def priority(adj, colors, sat, deg, uncolored_deg):
    n = adj.shape[0]
    unc = (colors == -1)
    scores = np.full(n, -1.0, dtype=np.float64)

    if not np.any(unc):
        return scores

    is_first_in_class = False
    cur_max_col = np.max(colors)

    if cur_max_col == -1:
        is_first_in_class = True
    else:
        in_cur_class = (colors == cur_max_col)
        if not np.any(adj[:, in_cur_class]):
            is_first_in_class = True

    if is_first_in_class:
        scores[unc] = sat[unc].astype(np.float64) * 1000000.0 + uncolored_deg[unc].astype(np.float64) * 1000.0 + deg[unc].astype(np.float64)
    else:
        in_cur_class = (colors == cur_max_col)
        cand = unc & (~np.any(adj[:, in_cur_class], axis=1))

        if np.any(cand):
            ne = adj.dot((unc & (~cand)).astype(np.int64))
            nc = adj.dot(cand.astype(np.int64))
            scores[cand] = ne[cand].astype(np.float64) * 1000000.0 - nc[cand].astype(np.float64) * 1000.0 + uncolored_deg[cand].astype(np.float64)
        else:
            scores[unc] = sat[unc].astype(np.float64) * 1000000.0 + uncolored_deg[unc].astype(np.float64)

    return scores
